<?php
declare(strict_types=1);
require __DIR__.'/lib/bootstrap.php'; require __DIR__.'/lib/layout.php'; require __DIR__.'/lib/mail_client.php'; require_permission('mail.read'); mail_client_ensure_tables();
$view=(string)($_GET['view']??'inbox'); if(!in_array($view,['inbox','sent','templates'],true))$view='inbox'; $filter=($_GET['filter']??'')==='unread'?'unread':'all'; $error=null;
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{verify_csrf();$action=(string)($_POST['action']??'');if($action==='send'){require_permission('mail.create');$message=[];foreach(['to','to_name','cc','bcc','subject','body','in_reply_to'] as $field)$message[$field]=trim((string)($_POST[$field]??''));mail_send_message($message);if($message['in_reply_to']!=='')mail_mark_contact_read((int)$message['in_reply_to'],true);audit('mail.create','mail',null,['to'=>$message['to'],'subject'=>$message['subject']]);flash('Message sent to '.$message['to'].'.');redirect('mail.php?view=sent');}if($action==='template.save'){require_permission('mail.update');$key=trim((string)$_POST['template_key']);$subject=trim((string)$_POST['subject']);$body=trim((string)$_POST['body']);if($key===''||$subject===''||$body==='')throw new RuntimeException('Template key, subject and body are required.');db()->prepare('INSERT INTO cms_mail_templates(template_key,subject,body) VALUES(?,?,?) ON DUPLICATE KEY UPDATE subject=VALUES(subject),body=VALUES(body)')->execute([$key,$subject,$body]);audit('mail.update','mail');flash('Mail template saved.');redirect('mail.php?view=templates');}}catch(Throwable $exception){$error=$exception->getMessage();}}
$open=null;$source=(string)($_GET['source']??'');$openId=(int)($_GET['open']??0);if($openId&&$source==='form'){$open=mail_contact_find($openId);if($open&&$open['status']==='unread')mail_mark_contact_read($openId);}if($openId&&$source==='sent'){$statement=db()->prepare('SELECT * FROM cms_sent_mail WHERE id=?');$statement->execute([$openId]);$open=$statement->fetch()?:null;if($open)$open['source']='sent';}
$inbox=$view==='inbox'?mail_contact_messages($filter):[];$unread=count(mail_contact_messages('unread'));$sent=$view==='sent'?db()->query('SELECT * FROM cms_sent_mail ORDER BY created_at DESC')->fetchAll():[];$templates=$view==='templates'?db()->query('SELECT * FROM cms_mail_templates ORDER BY template_key')->fetchAll():[];page_start('Mail','mail');
?><div class="mail-page-head"><h2><?=icon('mail')?>Mail</h2><p class="muted">Contact-form messages and outgoing mail in one place.</p></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><nav class="mail-tabs" aria-label="Mail navigation"><a class="<?=$view==='inbox'?'active':''?>" href="mail.php?view=inbox">Inbox<?php if($unread):?><b><?=e($unread)?></b><?php endif;?></a><a class="<?=$view==='sent'?'active':''?>" href="mail.php?view=sent">Sent</a><?php if(can('mail.create')):?><button type="button" class="mail-tab-button" data-open-panel="mailComposePanel">✎ Compose</button><?php endif;?><?php if(can('mail.update')):?><a class="<?=$view==='templates'?'active':''?>" href="mail.php?view=templates">Templates</a><?php endif;?></nav>
<?php if(can('mail.create')):?><section class="panel modal-panel mail-compose-modal" id="mailComposePanel" hidden><div class="panel-head"><h3 id="mailComposeTitle">Compose mail</h3><button class="button ghost" type="button" data-close-panel="mailComposePanel">Cancel</button></div><form method="post" id="mailComposeForm"><?=csrf_field()?><input type="hidden" name="action" value="send"><input type="hidden" name="to_name" value=""><input type="hidden" name="in_reply_to" value=""><div class="form-grid"><label>To<input name="to" type="email" placeholder="recipient@example.com" required></label><label>Cc<input name="cc" placeholder="Separate addresses with commas"></label></div><label>Bcc<input name="bcc" placeholder="Hidden recipients, separated with commas"></label><label>Subject<input name="subject" placeholder="What is this message about?" required></label><label>Message<textarea name="body" rows="12" placeholder="Write a clear, helpful reply." required></textarea></label><div class="editor-save-bar"><button class="button primary">Send message</button><button class="button ghost" type="button" data-close-panel="mailComposePanel">Cancel</button></div></form></section><?php endif;?>
<?php if($view==='sent'):?><section class="panel"><div class="panel-head"><div><h3>Sent mail</h3><p class="muted">Every outgoing message is kept here with its delivery status.</p></div></div><?php if(!$sent):?><p class="empty">No mail has been sent yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>#</th><th>Recipient</th><th>Subject</th><th>Status</th><th>Sent</th></tr></thead><tbody><?php foreach($sent as $index=>$item):?><tr><td class="serial"><?=e($index+1)?></td><td><?=e($item['to_name']?:$item['to_email'])?><small class="table-sub"><?=e($item['to_email'])?></small></td><td><a href="mail.php?view=sent&amp;open=<?=e($item['id'])?>&amp;source=sent"><?=e($item['subject'])?></a></td><td><span class="badge <?=e($item['status'])?>"><?=e($item['status'])?></span></td><td><?=e($item['created_at'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php if($open&&$open['source']==='sent'):?><section class="panel mail-reading"><div class="mail-reading-head"><div><h3><?=e($open['subject'])?></h3><p class="muted">To <?=e($open['to_name']?:$open['to_email'])?> · <?=e($open['created_at'])?></p></div><span class="badge <?=e($open['status'])?>"><?=e($open['status'])?></span></div><div class="mail-body"><?=nl2br(e((string)$open['body']))?></div><?php if($open['error_message']):?><div class="alert error">Delivery error: <?=e($open['error_message'])?></div><?php endif;?></section><?php endif;?>
<?php elseif($view==='templates'):?><section class="panel mail-template-editor"><div class="panel-head"><div><h3 id="mailTemplateFormTitle">Mail templates</h3><p class="muted">Use templates for recurring replies and notification messages.</p></div></div><form method="post" class="form-grid" id="mailTemplateForm"><?=csrf_field()?><input type="hidden" name="action" value="template.save"><label>Template key<input name="template_key" placeholder="e.g. enquiry.received" required></label><label>Subject<input name="subject" placeholder="e.g. We received your enquiry" required></label><label class="full-row">Message<textarea name="body" rows="7" placeholder="Write the reusable email message." required></textarea></label><div class="editor-save-bar"><button class="button primary" id="mailTemplateSaveButton">Save template</button><button class="button ghost" type="button" id="mailTemplateCancelButton" hidden>Cancel edit</button></div></form></section><section class="panel"><h3>Saved templates</h3><?php if(!$templates):?><p class="empty">No templates yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>#</th><th>Key</th><th>Subject</th><th>Updated</th><th class="actions">Actions</th></tr></thead><tbody><?php foreach($templates as $index=>$template):?><tr><td class="serial"><?=e($index+1)?></td><td><code><?=e($template['template_key'])?></code></td><td><?=e($template['subject'])?></td><td><?=e($template['updated_at'])?></td><td class="actions"><button class="table-action edit" type="button" data-mail-edit data-key="<?=e($template['template_key'])?>" data-subject="<?=e($template['subject'])?>" data-body="<?=e($template['body'])?>" title="Edit <?=e($template['template_key'])?>"><span aria-hidden="true">✎</span><span>Edit</span></button></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php else:?><div class="mail-filters"><a class="<?=$filter==='all'?'active':''?>" href="mail.php?view=inbox">All</a><a class="<?=$filter==='unread'?'active':''?>" href="mail.php?view=inbox&amp;filter=unread">Unread<?php if($unread):?> (<?=e($unread)?>)<?php endif;?></a></div><div class="mail-layout"><section class="panel mail-list"><?php if(!$inbox):?><p class="empty">No <?=e($filter==='unread'?'unread ':'')?>website messages.</p><?php else:foreach($inbox as $item):?><a class="mail-item <?=$item['status']==='unread'?'unread':''?> <?=($open&&$source==='form'&&(int)$open['id']===$item['id'])?'selected':''?>" href="mail.php?view=inbox&amp;open=<?=e($item['id'])?>&amp;source=form<?= $filter==='unread'?'&amp;filter=unread':''?>"><span class="mail-item-top"><strong><?=e($item['name'])?></strong><time><?=e(date('j M',strtotime($item['created_at'])))?></time></span><span><?=e($item['subject'])?></span><small><?=e(mb_substr($item['message'],0,120))?></small></a><?php endforeach;endif;?></section><section class="panel mail-reading"><?php if(!$open):?><div class="mail-empty"><span>✉</span><strong>Select a message</strong><p>Contact-form messages appear here. Select one to read and reply.</p></div><?php else:?><div class="mail-reading-head"><div><h3><?=e($open['subject'])?></h3><p class="muted"><strong><?=e($open['name'])?></strong> &lt;<?=e($open['email'])?>&gt; · <?=e($open['created_at'])?><?php if($open['phone']):?> · <?=e($open['phone'])?><?php endif;?></p></div><?php if(can('mail.create')):?><button class="button primary" type="button" data-mail-reply data-name="<?=e($open['name'])?>" data-email="<?=e($open['email'])?>" data-subject="<?=e($open['subject'])?>" data-message="<?=e($open['message'])?>" data-date="<?=e($open['created_at'])?>" data-id="<?=e($open['id'])?>">Reply</button><?php endif;?></div><div class="mail-body"><?=nl2br(e($open['message']))?></div><?php endif;?></section></div><?php endif;?><?php page_end();
